  python3 tools/logprob_oracle.py save NAME
  python3 tools/logprob_oracle.py check NAME
  python3 tools/log"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "build":
        prompts = build_prompts()
        for name, text in prompts.items():
            ids = tokenize(text)
            print(f"  {name:14s} chars={len(text):7d}  local tokens={len(ids):6d}  "
                  f"server tokens={server_prompt_tokens(text):6d}")
        return
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=1))
        print(f"  saved {path}")
        return
    if cmd == "check":
        name = sys.argv[2]
        reference = json.loads((D / f"{name}.json").read_text())
        current = collect(cached=reference)
        report = stats(reference, current)
        print_report(f"{name} vs current", report)
        return
    if cmd == "compare":
        a, b = sys.argv[2], sys.argv[3]
        ra = json.loads((D / f"{a}.json").read_text())
        rb = json.loads((D / f"{b}.json").read_text())
        print_report(f"{b} vs {a}", stats(ra, rb))
        print_report(f"{a} vs {b}", stats(rb, ra))
        return
    raise SystemExit(f"unknown command {cmd!r}")


if __name__ == "__main__":
    main()


